// Port Bilge Monitor & Alarm Engine
const SIDE = "Port";
const WARN_SECONDS = 120;   // 2 minutes warning
const ALARM_SECONDS = 300;  // 5 minutes critical alarm
const MAX_CYCLES_PER_HOUR = 4;

let running = context.get('running') || 0;
let runStartTime = context.get('run_start_time') || null;
let warningSent = context.get('warning_sent') || false;
let alarmSent = context.get('alarm_sent') || false;
let offAnomalySent = context.get('off_anomaly_sent') || false;
let cycleHistory = context.get('cycle_history') || [];
let autoMode = context.get('auto_mode') !== undefined ? context.get('auto_mode') : 1;
let switchState = context.get('switch_state') !== undefined ? context.get('switch_state') : 0;

const now = Date.now();
const outputs = [];

if (msg.topic === 'running') {
    const newRunning = Number(msg.payload) === 1 ? 1 : 0;
    if (newRunning === 1 && running === 0) {
        // Transition to RUNNING
        running = 1;
        runStartTime = now;
        warningSent = false;
        alarmSent = false;
        offAnomalySent = false;
        cycleHistory.push(now);
        cycleHistory = cycleHistory.filter(t => (now - t) <= 3600000);

        if (cycleHistory.length >= MAX_CYCLES_PER_HOUR) {
            outputs.push({
                type: 0,
                title: `${SIDE} Bilge Frequency Warning`,
                payload: `${SIDE} Bilge pump has cycled ${cycleHistory.length} times in the last hour.`,
                event: "FREQUENT_CYCLES"
            });
        }
    } else if (newRunning === 0 && running === 1) {
        // Transition to STOPPED
        const duration = runStartTime ? Math.floor((now - runStartTime) / 1000) : 0;
        if (warningSent || alarmSent || offAnomalySent) {
            outputs.push({
                type: 2,
                title: `${SIDE} Bilge Stopped`,
                payload: `${SIDE} Bilge pump stopped after running for ${duration}s.`,
                event: "PUMP_STOPPED"
            });
        }
        running = 0;
        runStartTime = null;
        warningSent = false;
        alarmSent = false;
        offAnomalySent = false;
    }
} else if (msg.topic === 'auto') {
    autoMode = Number(msg.payload) === 1 ? 1 : 0;
} else if (msg.topic === 'state') {
    switchState = Number(msg.payload) === 1 ? 1 : 0;
}

let mode = "OFF";
if (autoMode === 1) mode = "AUTO";
if (switchState === 1) mode = "MANUAL";

if (running === 1 && runStartTime) {
    const durationSec = Math.floor((now - runStartTime) / 1000);

    // 1. Off Anomaly Alarm: pump running while switched OFF
    if (mode === "OFF" && !offAnomalySent) {
        outputs.push({
            type: 1,
            title: `${SIDE} Bilge Critical`,
            payload: `ANOMALY: ${SIDE} Bilge pump is running while switched OFF!`,
            event: "OFF_ANOMALY"
        });
        offAnomalySent = true;
    }

    // 2. Continuous Run 5-Minute Critical Alarm
    if (durationSec >= ALARM_SECONDS && !alarmSent) {
        outputs.push({
            type: 1,
            title: `${SIDE} Bilge Critical Alarm`,
            payload: `CRITICAL: ${SIDE} Bilge pump running > 5 minutes (${Math.floor(durationSec/60)}m)! Check for water ingress.`,
            event: "RUN_5MIN_ALARM"
        });
        alarmSent = true;
    } else if (durationSec >= WARN_SECONDS && !warningSent) {
        // 3. Continuous Run 2-Minute Warning
        outputs.push({
            type: 0,
            title: `${SIDE} Bilge Warning`,
            payload: `${SIDE} Bilge pump running continuously for > 2 minutes (${durationSec}s).`,
            event: "RUN_2MIN_WARNING"
        });
        warningSent = true;
    }

    const statusColor = durationSec >= ALARM_SECONDS ? "red" : durationSec >= WARN_SECONDS ? "yellow" : "green";
    node.status({ fill: statusColor, shape: "dot", text: `RUNNING (${durationSec}s, Mode: ${mode})` });
} else {
    const recentCycles = cycleHistory.filter(t => (now - t) <= 3600000).length;
    node.status({ fill: "grey", shape: "ring", text: `Idle (${recentCycles} cycles/hr, Mode: ${mode})` });
}

context.set('running', running);
context.set('run_start_time', runStartTime);
context.set('warning_sent', warningSent);
context.set('alarm_sent', alarmSent);
context.set('off_anomaly_sent', offAnomalySent);
context.set('cycle_history', cycleHistory);
context.set('auto_mode', autoMode);
context.set('switch_state', switchState);

if (outputs.length > 0) {
    return [outputs];
}
return null;

